import { adminRegionsEnabled, getAdminRegion, listAdminRegions, type AdminRegion, type RegionShape } from '@/lib/adminRegionsServer';
import { buildFilters } from '@/lib/esQueryBuilder';
import { normalizeFilters, prepareMapQuery } from '@/lib/filterNormalize';

// The admin-1 assets are generated by scripts/build-maptiler-geo.mjs from the
// MapTiler Geocoding API (© MapTiler © OpenStreetMap contributors). Canonical
// geometry is verbatim (holes + islands included) and is BOTH what the client
// draws and what the ES geo_polygon filter matches — there is no per-listing
// classification. These tests pin the structural invariants, real-world
// coverage anchors, hole semantics, and the region-token cache keys.

function inRing(lng: number, lat: number, ring: { lat: number; lng: number }[]) {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const { lat: yi, lng: xi } = ring[i];
    const { lat: yj, lng: xj } = ring[j];
    if ((yi > lat) !== (yj > lat) && lng < ((xj - xi) * (lat - yi)) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}

// Even-odd, matching what MapLibre renders and what the ES clause expresses
// (outer geo_polygon minus hole geo_polygons).
function containsShape(shape: RegionShape, lng: number, lat: number) {
  return inRing(lng, lat, shape.outer) && !shape.holes.some((h) => inRing(lng, lat, h));
}

function contains(r: AdminRegion, lng: number, lat: number) {
  return r.shapes.some((s) => containsShape(s, lng, lat));
}

function interiorPoint(shape: RegionShape): { lng: number; lat: number } | null {
  const bb = [Infinity, Infinity, -Infinity, -Infinity];
  for (const p of shape.outer) {
    bb[0] = Math.min(bb[0], p.lng);
    bb[1] = Math.min(bb[1], p.lat);
    bb[2] = Math.max(bb[2], p.lng);
    bb[3] = Math.max(bb[3], p.lat);
  }
  for (let gx = 1; gx < 40; gx++) {
    for (let gy = 1; gy < 40; gy++) {
      const lng = bb[0] + ((bb[2] - bb[0]) * gx) / 40;
      const lat = bb[1] + ((bb[3] - bb[1]) * gy) / 40;
      if (containsShape(shape, lng, lat)) return { lng, lat };
    }
  }
  return null;
}

const COVERAGE_ANCHORS: [string, number, number, string][] = [
  // Maharashtra: the map and filter must include the whole coastal metro.
  ['IN-MH', 72.835, 18.94, 'Mumbai CST'],
  ['IN-MH', 72.815, 18.905, 'Colaba'],
  ['IN-MH', 72.83, 19.06, 'Bandra'],
  ['IN-MH', 72.978, 19.218, 'Thane'],
  ['IN-MH', 73.856, 18.52, 'Pune'],
  // UAE: MapTiler emirates are sea-envelope shapes — islands are inside.
  ['AE-DU', 55.061, 25.011, 'Jebel Ali'],
  ['AE-DU', 55.14, 25.08, 'Dubai Marina'],
  ['AE-DU', 55.274, 25.197, 'Burj Khalifa'],
  ['AE-DU', 56.12, 24.8, 'Hatta exclave'],
  ['AE-DU', 55.14, 25.135, 'Palm Jumeirah crescent'],
  ['AE-DU', 55.18, 25.23, 'World Islands'],
  ['AE-SH', 56.36, 25.34, 'Khor Fakkan exclave'],
  ['AE-AZ', 54.37, 24.45, 'Abu Dhabi city'],
  ['AE-AZ', 55.74, 24.21, 'Al Ain'],
  // Islands and enclaves that a coarse simplification would silently drop.
  ['IN-AN', 92.75, 11.66, 'Port Blair'],
  ['IN-AN', 92.78, 9.16, 'Car Nicobar'],
  ['IN-LD', 72.64, 10.56, 'Kavaratti'],
  ['IN-PY', 79.83, 11.93, 'Puducherry'],
  ['IN-PY', 75.5405, 11.7356, 'Mahe'],
  ['IN-PY', 79.83, 10.92, 'Karaikal'],
  ['IN-PY', 82.21, 16.73, 'Yanam'],
  ['IN-DN', 73.02, 20.27, 'Silvassa'],
  ['IN-DD', 72.83, 20.42, 'Daman'],
  ['IN-DD', 70.98, 20.71, 'Diu'],
  // J&K merges Ladakh (region.822 + region.1854) to keep the previous coverage.
  ['IN-JK', 74.8, 34.08, 'Srinagar'],
  ['IN-JK', 77.58, 34.15, 'Leh'],
  ['IN-JK', 76.13, 34.56, 'Kargil'],
  // Other markets
  ['IN-KA', 77.594, 12.972, 'Bangalore'],
  ['IN-DL', 77.209, 28.614, 'Delhi'],
  ['IN-TG', 78.487, 17.385, 'Hyderabad'],
];

describe('admin regions registry (MapTiler canonical)', () => {
  it('loads the tenant admin-1 manifest', () => {
    expect(adminRegionsEnabled()).toBe(true);
    const regions = listAdminRegions();
    // 36 India states/UTs + 7 UAE emirates
    expect(regions.length).toBe(43);
  });

  it('resolves regions by stable ISO id with a geometry token', () => {
    const mh = getAdminRegion('IN-MH');
    expect(mh).not.toBeNull();
    expect(mh!.name).toBe('Maharashtra');
    expect(mh!.countryCode).toBe('IN');
    expect(mh!.token).toMatch(/^IN-MH:[0-9a-f]{8,64}$/);

    const dubai = getAdminRegion('AE-DU');
    expect(dubai).not.toBeNull();
    expect(dubai!.countryCode).toBe('AE');
    expect(dubai!.name).toBe('Dubai');

    expect(getAdminRegion('')).toBeNull();
    expect(getAdminRegion('XX-XX')).toBeNull();
  });

  it('every region respects the canonical caps and has a usable bbox', () => {
    // Batched assertions: per-point expect() calls across ~500k vertices turn
    // this test into a 4-minute suite (jest matcher overhead), so violations
    // are collected and asserted once.
    const violations: string[] = [];
    for (const r of listAdminRegions()) {
      const points = r.shapes.reduce((a, s) => a + s.outer.length + s.holes.reduce((h, x) => h + x.length, 0), 0);
      if (points < 3) violations.push(`${r.id}: ${points} points`);
      if (points !== r.points) violations.push(`${r.id}: points mismatch ${points} vs ${r.points}`);
      if (points > 120000) violations.push(`${r.id}: ${points} points above tenant cap`);
      const rings = r.shapes.reduce((a, s) => a + 1 + s.holes.length, 0);
      if (rings !== r.ringCount) violations.push(`${r.id}: ring count mismatch`);
      if (rings > 1024) violations.push(`${r.id}: ${rings} rings above cap`);
      const holes = r.shapes.reduce((a, s) => a + s.holes.length, 0);
      if (holes !== r.holeCount) violations.push(`${r.id}: hole count mismatch`);
      const [minLng, minLat, maxLng, maxLat] = r.bbox;
      if (![minLng, minLat, maxLng, maxLat].every(Number.isFinite)) violations.push(`${r.id}: non-finite bbox`);
      if (!(minLng < maxLng && minLat < maxLat)) violations.push(`${r.id}: degenerate bbox`);
      let badPoints = 0;
      for (const s of r.shapes) {
        if (s.outer.length < 3) violations.push(`${r.id}: short outer ring`);
        for (const ring of [s.outer, ...s.holes]) {
          for (const p of ring) {
            if (
              !Number.isFinite(p.lat) || !Number.isFinite(p.lng) ||
              p.lat < -90 || p.lat > 90 || p.lng < -180 || p.lng > 180
            ) badPoints++;
          }
        }
      }
      if (badPoints > 0) violations.push(`${r.id}: ${badPoints} invalid vertices`);
    }
    expect(violations).toEqual([]);
  });

  it('normalization preserves canonical geometry exactly (no narrowing, no sampling)', () => {
    for (const r of listAdminRegions()) {
      const normalized = normalizeFilters({ polygonsWithHoles: r.shapes, regionToken: r.token }).polygonsWithHoles!;
      const points = normalized.reduce((a, s) => a + s.outer.length + s.holes.reduce((h, x) => h + x.length, 0), 0);
      expect(points).toBe(r.points);
      expect(normalized.length).toBe(r.shapes.length);
      expect(normalized.reduce((a, s) => a + s.holes.length, 0)).toBe(r.holeCount);
      expect(normalizeFilters({ polygonsWithHoles: r.shapes, regionToken: r.token }).regionToken).toBe(r.token);
    }
  });

  it('covers the real-world anchors the map and filter depend on', () => {
    for (const [id, lng, lat, label] of COVERAGE_ANCHORS) {
      const region = getAdminRegion(id);
      expect(region).not.toBeNull();
      if (!contains(region!, lng, lat)) throw new Error(`${label} (${lng},${lat}) is outside ${id}`);
    }
  });

  it('bounding boxes frame the anchor points', () => {
    const inBbox = (id: string, lng: number, lat: number) => {
      const r = getAdminRegion(id)!;
      return lat >= r.bbox[1] && lat <= r.bbox[3] && lng >= r.bbox[0] && lng <= r.bbox[2];
    };
    expect(inBbox('IN-MH', 72.877, 19.076)).toBe(true);
    expect(inBbox('AE-DU', 55.27, 25.204)).toBe(true);
    expect(inBbox('AE-AZ', 55.74, 24.21)).toBe(true);
  });

  it('preserves holes from MapTiler (Gujarat/Tamil Nadu/Maharashtra) and treats them as holes', () => {
    const gj = getAdminRegion('IN-GJ')!;
    expect(gj.holeCount).toBeGreaterThan(0);
    const holed = gj.shapes.find((s) => s.holes.length > 0)!;
    const probe = interiorPoint({ outer: holed.holes[0], holes: [] });
    expect(probe).not.toBeNull();
    // Inside the hole ⇒ outside the region (even-odd), even though the outer
    // ring contains the point.
    expect(inRing(probe!.lng, probe!.lat, holed.outer)).toBe(true);
    expect(containsShape(holed, probe!.lng, probe!.lat)).toBe(false);

    const tn = getAdminRegion('IN-TN')!;
    expect(tn.holeCount).toBe(9);
  });
});

// State filtering is a geo_polygon over the canonical shapes — the same
// geometry the outline draws. Holes are expressed as must_not geo_polygons
// because ES geo_polygon cannot carry holes itself.
describe('admin-1 filter construction', () => {
  const base = { bounds: { minLat: 18.8, maxLat: 19.3, minLng: 72.7, maxLng: 73.1 }, scope: 'both', sort: 'newest' };
  const tinyShape = {
    outer: [
      { lat: 19.0, lng: 72.8 },
      { lat: 19.0, lng: 73.0 },
      { lat: 19.2, lng: 73.0 },
      { lat: 19.2, lng: 72.8 },
    ],
    holes: [
      [
        { lat: 19.05, lng: 72.85 },
        { lat: 19.05, lng: 72.95 },
        { lat: 19.15, lng: 72.95 },
        { lat: 19.15, lng: 72.85 },
      ],
    ],
  };

  it('emits geo_polygon clauses and never admin1_id', () => {
    const mh = getAdminRegion('IN-MH')!;
    const { filters } = buildFilters({ ...base, polygonsWithHoles: mh.shapes }, 'both');
    const asText = JSON.stringify(filters);
    expect(asText).toContain('geo_polygon');
    expect(asText).not.toContain('admin1_id');
  });

  it('expresses holes as must_not geo_polygons', () => {
    const { filters } = buildFilters({ ...base, polygonsWithHoles: [tinyShape] }, 'both');
    const clause = filters.find((c: any) => c?.bool?.filter && c?.bool?.must_not);
    expect(clause).toBeTruthy();
    expect(clause.bool.filter[0].geo_polygon).toBeTruthy();
    expect(clause.bool.must_not.length).toBe(1);
    expect(clause.bool.must_not[0].geo_polygon).toBeTruthy();
  });

  it('unions multiple polygons via should', () => {
    const { filters } = buildFilters({ ...base, polygonsWithHoles: [tinyShape, { ...tinyShape, holes: [] }] }, 'both');
    const union = filters.find((c: any) => c?.bool?.should);
    expect(union).toBeTruthy();
    expect(union.bool.should.length).toBe(2);
  });

  it('text clauses demote to scoring-only inside a state selection', () => {
    const mh = getAdminRegion('IN-MH')!;
    const { must } = buildFilters({ ...base, polygonsWithHoles: mh.shapes, query: 'mumbai' }, 'both');
    const scoringOnly = must.find((c: any) => c?.bool?.should && c.bool.minimum_should_match === 0);
    expect(scoringOnly).toBeTruthy();
  });

  it('drops a token that arrives without shapes', () => {
    const a = normalizeFilters({ regionToken: 'IN-MH:deadbeef' });
    expect(a.regionToken).toBeUndefined();
  });
});

// The region token stands in for the megabyte-scale geometry in cache keys:
// identical tokens ⇒ identical keys regardless of vertex payload, different
// tokens ⇒ different keys. Without this, every state request pays a full FNV
// pass over ~30-48k points (measured ~40-90 ms per key).
describe('region token cache keys', () => {
  const bounds = { minLat: 18, maxLat: 20, minLng: 72, maxLng: 74 };
  const ring = (dx: number) => [
    { lat: 19.0, lng: 72.8 + dx },
    { lat: 19.0, lng: 73.0 + dx },
    { lat: 19.2, lng: 73.0 + dx },
    { lat: 19.2, lng: 72.8 + dx },
  ];

  it('same token ⇒ same keys across different vertex payloads', () => {
    const a = prepareMapQuery(bounds, { polygonsWithHoles: [{ outer: ring(0), holes: [] }], regionToken: 'IN-MH:aaaa1111' });
    const b = prepareMapQuery(bounds, { polygonsWithHoles: [{ outer: ring(0.0001), holes: [] }], regionToken: 'IN-MH:aaaa1111' });
    expect(a.markerKey).toBe(b.markerKey);
    expect(a.listKey).toBe(b.listKey);
  });

  it('different tokens ⇒ different keys', () => {
    const a = prepareMapQuery(bounds, { polygonsWithHoles: [{ outer: ring(0), holes: [] }], regionToken: 'IN-MH:aaaa1111' });
    const b = prepareMapQuery(bounds, { polygonsWithHoles: [{ outer: ring(0), holes: [] }], regionToken: 'IN-MH:bbbb2222' });
    expect(a.listKey).not.toBe(b.listKey);
  });

  it('boundary-less queries keep the legacy keys (token without shapes is dropped)', () => {
    const keyed = prepareMapQuery(bounds, { regionToken: 'IN-MH:aaaa1111' });
    expect(JSON.stringify(keyed.filters)).not.toContain('polygonsWithHoles');
    expect(keyed.filters.regionToken).toBeUndefined();
  });
});
